\mathrm{AdjHomBij}(F,G,\Phi)\Longleftrightarrow
\begin{cases}
\begin{gathered}
(\forall X\in\operatorname{Ob}\mathcal C)(\forall Y\in\operatorname{Ob}\mathcal D)\\
(\forall h\in\mathcal C(X,GY))(\exists!g\in\mathcal D(FX,Y))\
\Phi_{X,Y}(g)=h
\end{gathered}&\mathrm{AdjHomData}(F,G,\Phi),\\
\bot&\neg\mathrm{AdjHomData}(F,G,\Phi).
\end{cases}

\mathrm{AdjUnitCounit}(F,G,\eta,\epsilon)\Longleftrightarrow
\begin{cases}
\begin{gathered}
(\forall X\in\operatorname{Ob}\mathcal C)\
\epsilon_{FX}\circ F\eta_X=\operatorname{id}_{FX}\\
\land(\forall Y\in\operatorname{Ob}\mathcal D)\
G\epsilon_Y\circ\eta_{GY}=\operatorname{id}_{GY}
\end{gathered}&
\begin{gathered}
\mathrm{NatTrans}_{\mathcal C,\mathcal C}(\eta:\operatorname{Id}_{\mathcal C}\Rightarrow GF)\\
\land\mathrm{NatTrans}_{\mathcal D,\mathcal D}(\epsilon:FG\Rightarrow\operatorname{Id}_{\mathcal D})
\end{gathered},\\
\bot&\neg\left(
\begin{gathered}
\mathrm{NatTrans}_{\mathcal C,\mathcal C}(\eta:\operatorname{Id}_{\mathcal C}\Rightarrow GF)\\
\land\mathrm{NatTrans}_{\mathcal D,\mathcal D}(\epsilon:FG\Rightarrow\operatorname{Id}_{\mathcal D})
\end{gathered}\right).
\end{cases}
